-- CarworX staging businesses. SYNTHETIC DATA ONLY: every business,
-- address and check below is invented. They are not labelled on screen, so
-- staging looks like the real directory; the fixtures are recognisable in the
-- data by their ids (de3...) and provenance references (staging-seed-NN).
-- Coordinates are suburb centres, not real premises. Addresses use street
-- names made up for these suburbs.
--
-- Not loaded by `supabase db reset` (config.toml seeds only seed.sql), so the
-- test suites keep their fixtures. Apply by hand AFTER seed.sql (it reuses the
-- synthetic admin 5eed...0004 as the verifier):
--   psql "$DB_URL" -v ON_ERROR_STOP=1 -f supabase/seed-staging.sql
-- Safe to run again: it removes its own rows first. Undo with
-- seed-staging-remove.sql.
begin;
-- Hard guard: this file runs only where the synthetic seed (seed.sql) ran,
-- i.e. a local stack or staging. Production never has the synthetic admin
-- below, so there the whole file stops before changing anything.
do $guard$
begin
  if not exists (
    select 1 from auth.users
    where id = '5eed0000-0000-4000-8000-000000000004'
      and email = 'synthetic.admin@example.test'
  ) then
    raise exception 'refusing to run: no synthetic seed here (local or staging only)';
  end if;
end
$guard$;

-- Remove any earlier copy (children first). Only these fixtures' ids (de3...) match.
delete from public.verifications where organisation_id::text like 'de300000-%';
delete from public.listing_hours where organisation_id::text like 'de300000-%';
delete from public.listing_services where organisation_id::text like 'de300000-%';
delete from public.service_areas where organisation_id::text like 'de300000-%';
delete from public.listings where organisation_id::text like 'de300000-%';
delete from public.branches where organisation_id::text like 'de300000-%';
delete from public.coordinate_sources where organisation_id::text like 'de300000-%';
delete from public.organisations where id::text like 'de300000-%';









-- Readable service names. seed.sql names them "Synthetic ...";
-- only rows still carrying that name change, and seed-staging-remove.sql puts
-- them back.
update public.services s set name = v.name
from (values ('wash','Wash & valet'),('service','Mechanical service'),('tyres','Tyres & alignment'),
 ('paint','Panel & paint'),('electrical','Auto electrical'),('mobile-repair','Mobile mechanic'),
 ('glass','Windscreen & glass')) v(slug, name)
where s.slug = v.slug and s.name like 'Synthetic %';

commit;
